import pandas as pd
import numpy as np

# ---------------------------------------------------------
# Files
# ---------------------------------------------------------

CAL = "REVIEWER_2023_CALIBRATION_SCALES.csv"

# Use the corrected frozen-model evaluation output
# generated by the existing reviewer experiment.
# We reconstruct 2024 predictions directly from the
# saved latent-model evaluation if available.
#
# First inspect likely files.
import glob

print("\n==========================================")
print("FINAL DEVIATION ANALYSIS")
print("==========================================")

print("\nCandidate latent/evaluation files:")
for f in glob.glob("*LATENT*.csv") + glob.glob("*2024*.csv"):
    print(f)

cal = pd.read_csv(CAL)

print("\n2023 calibration scales:")
print(cal.to_string(index=False))

# ---------------------------------------------------------
# Locate 2024 latent prediction file
# ---------------------------------------------------------

candidates = [
    "GLOBAL_LATENT_2024_PREDICTIONS.csv",
    "GLOBAL_LATENT_TRANSITION_2024_RESULTS.csv",
    "GLOBAL_LATENT_2024_RESULTS.csv",
    "LATENT_2024_RESULTS.csv"
]

pred_file = None

for f in candidates:
    try:
        tmp = pd.read_csv(f)
        if {"site_id", "date", "feature"}.issubset(tmp.columns):
            pred_file = f
            pred = tmp.copy()
            break
    except FileNotFoundError:
        pass

if pred_file is None:
    print("\nCould not automatically identify a 2024 latent prediction file.")
    print("Available candidate CSV files:")
    print(
        glob.glob("*.csv")
    )
    raise SystemExit(
        "\nSTOP: paste the filenames printed above."
    )

print("\nUsing 2024 prediction file:")
print(pred_file)

print("\nPrediction columns:")
print(pred.columns.tolist())

# ---------------------------------------------------------
# Normalize column names
# ---------------------------------------------------------

pred["date"] = pd.to_datetime(pred["date"])

if "observation" in pred.columns:
    pred["actual"] = pred["observation"]

if "prediction" in pred.columns:
    pred["predicted"] = pred["prediction"]

required = [
    "site_id",
    "date",
    "feature",
    "actual",
    "predicted"
]

missing = [
    x for x in required
    if x not in pred.columns
]

if missing:
    raise SystemExit(
        "Missing required columns: "
        + str(missing)
    )

# ---------------------------------------------------------
# Calibration scale lookup
# ---------------------------------------------------------

scale_map = dict(
    zip(
        cal["feature"],
        cal["robust_scale"]
    )
)

pred["scale"] = pred["feature"].map(
    scale_map
)

pred = pred.dropna(
    subset=["actual", "predicted", "scale"]
).copy()

# 2024 only
pred = pred[
    pred["date"].dt.year == 2024
].copy()

pred["abs_error"] = (
    pred["actual"] -
    pred["predicted"]
).abs()

pred["standardized_deviation"] = (
    pred["abs_error"] /
    pred["scale"]
)

# ---------------------------------------------------------
# Feature-level 95th percentile thresholds
# ---------------------------------------------------------

p95_map = dict(
    zip(
        cal["feature"],
        cal["p95"]
    )
)

pred["above_p95"] = (
    pred["abs_error"]
    >= pred["feature"].map(p95_map)
)

# ---------------------------------------------------------
# Multi-sensor site-month aggregation
# ---------------------------------------------------------

pred["sensor"] = np.where(
    pred["feature"].isin(
        ["NDVI", "EVI", "NDWI"]
    ),
    "S2",
    "S1"
)

monthly = (
    pred
    .groupby(
        [
            "site_id",
            "date"
        ]
    )
    .agg(
        crop=("crop", "first")
        if "crop" in pred.columns
        else ("site_id", "first"),
        country=("country", "first")
        if "country" in pred.columns
        else ("site_id", "first"),
        n_features=("feature", "count"),
        mean_standardized_deviation=(
            "standardized_deviation",
            "mean"
        ),
        max_standardized_deviation=(
            "standardized_deviation",
            "max"
        ),
        n_features_above_p95=(
            "above_p95",
            "sum"
        )
    )
    .reset_index()
)

# Determine whether each sensor contributes
sensor_flags = (
    pred
    .groupby(
        ["site_id", "date", "sensor"]
    )["above_p95"]
    .any()
    .unstack(fill_value=False)
    .reset_index()
)

if "S1" not in sensor_flags.columns:
    sensor_flags["S1"] = False

if "S2" not in sensor_flags.columns:
    sensor_flags["S2"] = False

monthly = monthly.merge(
    sensor_flags,
    on=["site_id", "date"],
    how="left"
)

monthly["multi_sensor_event"] = (
    monthly["S1"].fillna(False)
    &
    monthly["S2"].fillna(False)
)

# Require at least two feature-level exceedances,
# and contributions from both sensors.
monthly["robust_multi_sensor_event"] = (
    monthly["multi_sensor_event"]
    &
    (monthly["n_features_above_p95"] >= 2)
)

# ---------------------------------------------------------
# Persistence
# ---------------------------------------------------------

monthly = monthly.sort_values(
    ["site_id", "date"]
)

monthly["previous_event"] = (
    monthly
    .groupby("site_id")[
        "robust_multi_sensor_event"
    ]
    .shift(1)
    .fillna(False)
)

monthly["persistent_event"] = (
    monthly["robust_multi_sensor_event"]
    &
    monthly["previous_event"]
)

# ---------------------------------------------------------
# Results
# ---------------------------------------------------------

events = monthly[
    monthly["robust_multi_sensor_event"]
].copy()

persistent = monthly[
    monthly["persistent_event"]
].copy()

print("\n==========================================")
print("2024 FINAL DEVIATION RESULTS")
print("==========================================")

print(
    "2024 site-months:",
    len(monthly)
)

print(
    "Multi-sensor events:",
    len(events)
)

print(
    "Multi-sensor event rate:",
    round(
        len(events) / len(monthly),
        4
    )
)

print(
    "Sites affected:",
    events["site_id"].nunique()
)

print(
    "Persistent consecutive event months:",
    len(persistent)
)

print("\nEvent table:")

if len(events):
    print(
        events[
            [
                "site_id",
                "date",
                "crop",
                "country",
                "mean_standardized_deviation",
                "max_standardized_deviation",
                "n_features_above_p95",
                "S1",
                "S2",
                "persistent_event"
            ]
        ]
        .sort_values(
            "max_standardized_deviation",
            ascending=False
        )
        .to_string(index=False)
    )
else:
    print("No multi-sensor events.")

# ---------------------------------------------------------
# Site summary
# ---------------------------------------------------------

site_summary = (
    monthly
    .groupby(
        [
            "site_id",
            "crop",
            "country"
        ]
    )
    .agg(
        site_months=("date", "count"),
        mean_deviation=(
            "mean_standardized_deviation",
            "mean"
        ),
        max_deviation=(
            "max_standardized_deviation",
            "max"
        ),
        multi_sensor_events=(
            "robust_multi_sensor_event",
            "sum"
        ),
        persistent_events=(
            "persistent_event",
            "sum"
        )
    )
    .reset_index()
    .sort_values(
        "multi_sensor_events",
        ascending=False
    )
)

print("\n==========================================")
print("SITE SUMMARY")
print("==========================================")

print(
    site_summary.to_string(index=False)
)

# ---------------------------------------------------------
# Feature summary
# ---------------------------------------------------------

feature_summary = (
    pred
    .groupby("feature")
    .agg(
        observations=("abs_error", "count"),
        mean_abs_error=("abs_error", "mean"),
        mean_standardized_deviation=(
            "standardized_deviation",
            "mean"
        ),
        p95_exceedance_rate=(
            "above_p95",
            "mean"
        )
    )
    .reset_index()
)

print("\n==========================================")
print("FEATURE SUMMARY")
print("==========================================")

print(
    feature_summary.to_string(index=False)
)

# ---------------------------------------------------------
# Save
# ---------------------------------------------------------

pred.to_csv(
    "FINAL_2024_STANDARDIZED_DEVIATIONS.csv",
    index=False
)

monthly.to_csv(
    "FINAL_2024_SITE_MONTH_DEVIATIONS.csv",
    index=False
)

events.to_csv(
    "FINAL_2024_MULTISENSOR_EVENTS.csv",
    index=False
)

persistent.to_csv(
    "FINAL_2024_PERSISTENT_EVENTS.csv",
    index=False
)

site_summary.to_csv(
    "FINAL_2024_DEVIATION_SITE_SUMMARY.csv",
    index=False
)

feature_summary.to_csv(
    "FINAL_2024_DEVIATION_FEATURE_SUMMARY.csv",
    index=False
)

print("\nSaved final deviation files.")
